onClick:
{{
(() => {
  const multiselectFields = ['sm', 'partners', 'protocol_types', 'protocols', 'purposes', 'restrictions'];
  const excludeFields = ['locations_stages', 'legacy_ref', 'created_at'];

  const normalize = (obj) => {
    const cleaned = _.omit(obj, excludeFields);
    return _.mapValues(cleaned, (val, key) => {
      if (multiselectFields.includes(key)) {
        return (val || []).map(String).sort();
      }
      // null in undefined naj bosta enaka
      if (val === null || val === undefined) return '';
      return val;
    });
  };

  const formNormalized = normalize(JSONForm1.formData);
  const viewNormalized = normalize(appsmith.store.viewData);

  // Polja, ki jih forma ne vrača → obravnavaj kot nespremenjena
  ['external', 'status_code', 'primary_author'].forEach((key) => {
    if (formNormalized[key] === undefined || formNormalized[key] === '') {
      formNormalized[key] = viewNormalized[key] ?? '';
    }
  });

  return !_.isEqual(formNormalized, viewNormalized)
    ? showAlert("You have unsaved changes! Please click Confirm to save.", "warning")
    : closeModal('View_modal');
})()
}}
